-- 리눅스 세트 226. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 단원·display_order·아이콘은 통합 시 따로 정한다. docs/specs/spec_linux_disk_usage_set.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 226, '디스크 사용량 점검 손에 익히기: df, du, sort -h, ls -lhS, find -size', '디스크가 찼다는 알람을 받았을 때 하는 일을 순서대로 연습합니다. df -h/-i 로 어느 디스크인지 보고, du -sh·--max-depth 로 큰 폴더를 좁히고, sort -h·ls -lhS·find -size 로 큰 파일을 찾고, 지우기 전후 크기를 비교합니다. df 와 du 가 어긋나는 이유도 짚습니다.', 'linux', '리눅스'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 226);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 226, 1, '디스크 전체 사용률 보기', '디스크가 얼마나 찼는지 보는 첫걸음입니다. 루트(`/`)가 올라 있는 파일시스템의 용량을 **사람이 읽기 쉬운 단위**로 `/tmp/df.txt` 에 저장하세요. (제목 줄과 `/` 한 줄, 모두 2줄)', '`df` 는 파일시스템별 용량을 보여 줍니다. `-h` 를 붙이면 `G`, `M` 같은 단위로 나오고, 마지막에 경로(`/`)를 주면 그 경로가 속한 줄만 나와요.', 'df -h / > /tmp/df.txt
cat /tmp/df.txt

# Size(전체) Used(사용) Avail(남음) Use%(사용률) Mounted on(마운트 위치). 장애 때 가장 먼저 치는 명령', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab/logs /tmp/lab/data /tmp/lab/media /tmp/lab/many; head -c 3145728 /dev/zero > /tmp/lab/logs/app.log; head -c 12582912 /dev/zero > /tmp/lab/logs/db.log; head -c 524288 /dev/zero > /tmp/lab/logs/old.log; head -c 20971520 /dev/zero > /tmp/lab/data/dump.sql; head -c 5767168 /dev/zero > /tmp/lab/data/cache.bin; head -c 31457280 /dev/zero > /tmp/lab/media/movie.bin; head -c 3670016 /dev/zero > /tmp/lab/media/thumb.bin; for i in $(seq 1 300); do echo x > /tmp/lab/many/f$i; done; true"]', '["sh", "-c", "( head -n 1 /tmp/df.txt | grep -q Filesystem ) && ( tail -n 1 /tmp/df.txt | grep -q \\"%\\" ) && ( [ \\"$(wc -l < /tmp/df.txt)\\" -eq 2 ] && tail -n 1 /tmp/df.txt | grep -q \\" /$\\" )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "제목 줄에 Filesystem 이 있다", "cmd": ["sh", "-c", "head -n 1 /tmp/df.txt | grep -q Filesystem"]}, {"label": "사용률(%)이 있는 줄이 있다", "cmd": ["sh", "-c", "tail -n 1 /tmp/df.txt | grep -q \\"%\\""]}, {"label": "루트(/) 한 줄만 있다 (2줄)", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/df.txt)\\" -eq 2 ] && tail -n 1 /tmp/df.txt | grep -q \\" /$\\""]}]', '[{"title": "GNU coreutils 매뉴얼 (df, du, ls, sort)", "url": "https://www.gnu.org/software/coreutils/manual/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 226 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 226, 2, 'inode 사용률 보기', '용량은 남았는데 파일이 안 만들어질 때는 **inode(파일 개수 한도)** 가 찬 경우가 있습니다. 루트(`/`)의 inode 사용 현황을 `/tmp/inode.txt` 에 저장하세요.', '`df` 에 `-i` 를 붙이면 용량 대신 inode 개수(`Inodes`, `IUsed`, `IFree`, `IUse%`)를 보여 줍니다.', 'df -i / > /tmp/inode.txt
cat /tmp/inode.txt

# 작은 파일이 수백만 개 쌓이면 용량(Use%)은 한참 남아도 IUse% 가 100% 가 되어 파일을 못 만든다', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab/logs /tmp/lab/data /tmp/lab/media /tmp/lab/many; head -c 3145728 /dev/zero > /tmp/lab/logs/app.log; head -c 12582912 /dev/zero > /tmp/lab/logs/db.log; head -c 524288 /dev/zero > /tmp/lab/logs/old.log; head -c 20971520 /dev/zero > /tmp/lab/data/dump.sql; head -c 5767168 /dev/zero > /tmp/lab/data/cache.bin; head -c 31457280 /dev/zero > /tmp/lab/media/movie.bin; head -c 3670016 /dev/zero > /tmp/lab/media/thumb.bin; for i in $(seq 1 300); do echo x > /tmp/lab/many/f$i; done; true"]', '["sh", "-c", "( head -n 1 /tmp/inode.txt | grep -q \\"IUse%\\" ) && ( tail -n 1 /tmp/inode.txt | grep -q \\" /$\\" )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "제목 줄에 IUse% 가 있다", "cmd": ["sh", "-c", "head -n 1 /tmp/inode.txt | grep -q \\"IUse%\\""]}, {"label": "루트(/) 줄이 있다", "cmd": ["sh", "-c", "tail -n 1 /tmp/inode.txt | grep -q \\" /$\\""]}]', '[{"title": "GNU coreutils 매뉴얼 (df, du, ls, sort)", "url": "https://www.gnu.org/software/coreutils/manual/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 226 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 226, 3, '디렉터리 하나의 크기', '디스크가 찼다면 어느 폴더가 큰지 찾아야 합니다. `/tmp/lab/logs` 폴더가 **통째로 차지하는 크기**를 한 줄로 `/tmp/logs_size.txt` 에 저장하세요. (`16M /tmp/lab/logs` 처럼 나옵니다)', '`du` 는 폴더가 차지하는 크기를 셉니다. `-s`(summarize)는 안쪽을 일일이 나열하지 않고 합계만, `-h` 는 읽기 쉬운 단위로 보여 줘요.', 'du -sh /tmp/lab/logs > /tmp/logs_size.txt
cat /tmp/logs_size.txt

# -s 가 없으면 하위 폴더·파일을 전부 나열한다. 합계만 필요할 땐 -sh', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab/logs /tmp/lab/data /tmp/lab/media /tmp/lab/many; head -c 3145728 /dev/zero > /tmp/lab/logs/app.log; head -c 12582912 /dev/zero > /tmp/lab/logs/db.log; head -c 524288 /dev/zero > /tmp/lab/logs/old.log; head -c 20971520 /dev/zero > /tmp/lab/data/dump.sql; head -c 5767168 /dev/zero > /tmp/lab/data/cache.bin; head -c 31457280 /dev/zero > /tmp/lab/media/movie.bin; head -c 3670016 /dev/zero > /tmp/lab/media/thumb.bin; for i in $(seq 1 300); do echo x > /tmp/lab/many/f$i; done; true"]', '["sh", "-c", "( [ \\"$(wc -l < /tmp/logs_size.txt)\\" -eq 1 ] ) && ( grep -q \\"^16M[[:space:]]/tmp/lab/logs$\\" /tmp/logs_size.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "한 줄이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/logs_size.txt)\\" -eq 1 ]"]}, {"label": "크기가 16M 이고 경로가 맞다", "cmd": ["sh", "-c", "grep -q \\"^16M[[:space:]]/tmp/lab/logs$\\" /tmp/logs_size.txt"]}]', '[{"title": "GNU coreutils 매뉴얼 (df, du, ls, sort)", "url": "https://www.gnu.org/software/coreutils/manual/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 226 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 226, 4, '한 단계 아래만 펼쳐 보기', '`/tmp/lab` 바로 아래 폴더들이 **각각 얼마씩** 차지하는지, 그리고 `/tmp/lab` 전체 합계까지 `/tmp/depth.txt` 에 저장하세요. 파일 하나하나는 나오지 않아야 합니다.', '`du -h` 에 `--max-depth=1` 을 주면 지정한 폴더와 그 바로 아래 폴더까지만 보여 줍니다. 깊이를 2, 3 으로 늘려 가며 파고들 수도 있어요.', 'du -h --max-depth=1 /tmp/lab > /tmp/depth.txt
cat /tmp/depth.txt

# 맨 아래 줄은 /tmp/lab 전체 합계. "큰 폴더 찾기"는 이렇게 한 단계씩 내려가며 범위를 좁히는 일이다', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab/logs /tmp/lab/data /tmp/lab/media /tmp/lab/many; head -c 3145728 /dev/zero > /tmp/lab/logs/app.log; head -c 12582912 /dev/zero > /tmp/lab/logs/db.log; head -c 524288 /dev/zero > /tmp/lab/logs/old.log; head -c 20971520 /dev/zero > /tmp/lab/data/dump.sql; head -c 5767168 /dev/zero > /tmp/lab/data/cache.bin; head -c 31457280 /dev/zero > /tmp/lab/media/movie.bin; head -c 3670016 /dev/zero > /tmp/lab/media/thumb.bin; for i in $(seq 1 300); do echo x > /tmp/lab/many/f$i; done; true"]', '["sh", "-c", "( grep -q \\"^26M[[:space:]]/tmp/lab/data$\\" /tmp/depth.txt ) && ( grep -q \\"^34M[[:space:]]/tmp/lab/media$\\" /tmp/depth.txt ) && ( grep -Eq \\"^[0-9.]+M[[:space:]]/tmp/lab$\\" /tmp/depth.txt ) && ( ! grep -q \\"dump.sql\\" /tmp/depth.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "data 폴더가 26M 로 보인다", "cmd": ["sh", "-c", "grep -q \\"^26M[[:space:]]/tmp/lab/data$\\" /tmp/depth.txt"]}, {"label": "media 폴더가 34M 로 보인다", "cmd": ["sh", "-c", "grep -q \\"^34M[[:space:]]/tmp/lab/media$\\" /tmp/depth.txt"]}, {"label": "/tmp/lab 합계 줄이 있다", "cmd": ["sh", "-c", "grep -Eq \\"^[0-9.]+M[[:space:]]/tmp/lab$\\" /tmp/depth.txt"]}, {"label": "파일 단위 줄은 없다", "cmd": ["sh", "-c", "! grep -q \\"dump.sql\\" /tmp/depth.txt"]}]', '[{"title": "GNU coreutils 매뉴얼 (df, du, ls, sort)", "url": "https://www.gnu.org/software/coreutils/manual/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 226 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 226, 5, '폴더 안 파일을 큰 순서로', '`/tmp/lab/data` 안의 파일을 **크기가 큰 것부터** 자세히(크기 포함) 나열해 `/tmp/ls.txt` 에 저장하세요. 크기는 `20M` 같은 읽기 쉬운 단위여야 합니다.', '`ls -l` 은 자세히, `-h` 는 읽기 쉬운 단위, `-S` 는 크기순(큰 것이 위)입니다. 세 개를 합쳐 `-lhS` 로 씁니다.', 'ls -lhS /tmp/lab/data > /tmp/ls.txt
cat /tmp/ls.txt

# -S 큰 파일 순, -t 는 최근 수정 순, -r 을 더하면 거꾸로. 파일 몇 개짜리 폴더를 훑을 때 du 보다 빠르다', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab/logs /tmp/lab/data /tmp/lab/media /tmp/lab/many; head -c 3145728 /dev/zero > /tmp/lab/logs/app.log; head -c 12582912 /dev/zero > /tmp/lab/logs/db.log; head -c 524288 /dev/zero > /tmp/lab/logs/old.log; head -c 20971520 /dev/zero > /tmp/lab/data/dump.sql; head -c 5767168 /dev/zero > /tmp/lab/data/cache.bin; head -c 31457280 /dev/zero > /tmp/lab/media/movie.bin; head -c 3670016 /dev/zero > /tmp/lab/media/thumb.bin; for i in $(seq 1 300); do echo x > /tmp/lab/many/f$i; done; true"]', '["sh", "-c", "( grep dump.sql /tmp/ls.txt | grep -q \\" 20M \\" ) && ( a=$(grep -n dump.sql /tmp/ls.txt | cut -d: -f1); b=$(grep -n cache.bin /tmp/ls.txt | cut -d: -f1); [ -n \\"$a\\" ] && [ -n \\"$b\\" ] && [ \\"$a\\" -lt \\"$b\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "dump.sql 이 20M 로 보인다", "cmd": ["sh", "-c", "grep dump.sql /tmp/ls.txt | grep -q \\" 20M \\""]}, {"label": "dump.sql 이 cache.bin 보다 위에 있다", "cmd": ["sh", "-c", "a=$(grep -n dump.sql /tmp/ls.txt | cut -d: -f1); b=$(grep -n cache.bin /tmp/ls.txt | cut -d: -f1); [ -n \\"$a\\" ] && [ -n \\"$b\\" ] && [ \\"$a\\" -lt \\"$b\\" ]"]}]', '[{"title": "GNU coreutils 매뉴얼 (df, du, ls, sort)", "url": "https://www.gnu.org/software/coreutils/manual/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 226 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 226, 6, '큰 순서로 정렬하기', '`/tmp/lab` 바로 아래 폴더를 **큰 것부터** 보는 명령입니다. 한 단계만 펼치고(`--max-depth`), 사람이 읽는 단위(`M`, `G`)가 섞여 있어도 올바르게 정렬하는 옵션을 빈칸에 채우세요.', '`sort -n` 은 숫자만 비교해서 `9M` 과 `10M` 을 잘못 정렬해요. 단위 글자(K, M, G)를 이해하는 옵션은 `-h`, 큰 순서(거꾸로)는 `-r` 입니다.', NULL, NULL, '[]', 'fill', '["1", "s", "rh", "nr", "depth", "k"]', NULL, '`--max-depth=1` 은 한 단계 아래까지만, `sort -rh` 는 **h**uman 단위를 이해하며 **r**everse(큰 것이 위)로 정렬합니다. `-nr` 은 단위를 몰라 `9M` 을 `10M` 보다 크다고 볼 수 있습니다. `du ... | sort -rh | head` 는 "큰 폴더 찾기"의 기본 조합입니다.', '[0, 2]', 'du -h --max-depth={0} /tmp/lab | sort -{1}', NULL, '[{"title": "GNU coreutils 매뉴얼 (df, du, ls, sort)", "url": "https://www.gnu.org/software/coreutils/manual/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 226 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 226, 7, '가장 큰 폴더 두 개', '`/tmp/lab` 바로 아래 폴더 중 **가장 큰 두 개**를 큰 순서로 `/tmp/top2.txt` 에 저장하세요. (두 줄, 크기와 경로)', '`du -sh /tmp/lab/*` 은 폴더마다 합계 한 줄씩 줍니다. 앞 문제의 정렬을 이어 붙이고, 위의 몇 줄만 남기려면 `head -n 2` 를 쓰세요.', 'du -sh /tmp/lab/* | sort -rh | head -n 2 > /tmp/top2.txt
cat /tmp/top2.txt

# du | sort -rh | head 는 "무엇이 제일 큰가"를 한 줄로 묻는 가장 흔한 조합이다', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab/logs /tmp/lab/data /tmp/lab/media /tmp/lab/many; head -c 3145728 /dev/zero > /tmp/lab/logs/app.log; head -c 12582912 /dev/zero > /tmp/lab/logs/db.log; head -c 524288 /dev/zero > /tmp/lab/logs/old.log; head -c 20971520 /dev/zero > /tmp/lab/data/dump.sql; head -c 5767168 /dev/zero > /tmp/lab/data/cache.bin; head -c 31457280 /dev/zero > /tmp/lab/media/movie.bin; head -c 3670016 /dev/zero > /tmp/lab/media/thumb.bin; for i in $(seq 1 300); do echo x > /tmp/lab/many/f$i; done; true"]', '["sh", "-c", "( [ \\"$(wc -l < /tmp/top2.txt)\\" -eq 2 ] ) && ( sed -n 1p /tmp/top2.txt | grep -q \\"^34M[[:space:]]/tmp/lab/media$\\" ) && ( sed -n 2p /tmp/top2.txt | grep -q \\"^26M[[:space:]]/tmp/lab/data$\\" )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "두 줄이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/top2.txt)\\" -eq 2 ]"]}, {"label": "첫 줄이 media 이다", "cmd": ["sh", "-c", "sed -n 1p /tmp/top2.txt | grep -q \\"^34M[[:space:]]/tmp/lab/media$\\""]}, {"label": "둘째 줄이 data 이다", "cmd": ["sh", "-c", "sed -n 2p /tmp/top2.txt | grep -q \\"^26M[[:space:]]/tmp/lab/data$\\""]}]', '[{"title": "GNU coreutils 매뉴얼 (df, du, ls, sort)", "url": "https://www.gnu.org/software/coreutils/manual/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 226 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 226, 8, '10MB 넘는 파일 찾기', '`/tmp/lab` 아래에서 **10MB 보다 큰 일반 파일**의 경로만 `/tmp/big.txt` 에 한 줄에 하나씩 저장하세요.', '`find 경로 -type f -size +10M` 처럼 쓰면 됩니다. `-type f` 는 파일만, `+10M` 은 10MB 보다 큰 것(`-` 는 작은 것)을 뜻해요.', 'find /tmp/lab -type f -size +10M > /tmp/big.txt
cat /tmp/big.txt

# 단위: k, M, G. +100M 처럼 기준만 바꿔 서버 어디서든 "큰 파일 후보"를 뽑을 수 있다', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab/logs /tmp/lab/data /tmp/lab/media /tmp/lab/many; head -c 3145728 /dev/zero > /tmp/lab/logs/app.log; head -c 12582912 /dev/zero > /tmp/lab/logs/db.log; head -c 524288 /dev/zero > /tmp/lab/logs/old.log; head -c 20971520 /dev/zero > /tmp/lab/data/dump.sql; head -c 5767168 /dev/zero > /tmp/lab/data/cache.bin; head -c 31457280 /dev/zero > /tmp/lab/media/movie.bin; head -c 3670016 /dev/zero > /tmp/lab/media/thumb.bin; for i in $(seq 1 300); do echo x > /tmp/lab/many/f$i; done; true"]', '["sh", "-c", "( grep -q \\"/tmp/lab/data/dump.sql$\\" /tmp/big.txt ) && ( grep -q \\"/tmp/lab/logs/db.log$\\" /tmp/big.txt ) && ( grep -q \\"/tmp/lab/media/movie.bin$\\" /tmp/big.txt ) && ( [ \\"$(wc -l < /tmp/big.txt)\\" -eq 3 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "dump.sql 이 있다", "cmd": ["sh", "-c", "grep -q \\"/tmp/lab/data/dump.sql$\\" /tmp/big.txt"]}, {"label": "db.log 가 있다", "cmd": ["sh", "-c", "grep -q \\"/tmp/lab/logs/db.log$\\" /tmp/big.txt"]}, {"label": "movie.bin 이 있다", "cmd": ["sh", "-c", "grep -q \\"/tmp/lab/media/movie.bin$\\" /tmp/big.txt"]}, {"label": "작은 파일은 없다 (3줄)", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/big.txt)\\" -eq 3 ]"]}]', '[{"title": "GNU coreutils 매뉴얼 (df, du, ls, sort)", "url": "https://www.gnu.org/software/coreutils/manual/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 226 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 226, 9, '가장 큰 파일 세 개', '`/tmp/lab` 아래 모든 **파일 중 가장 큰 세 개**를 큰 순서로 `/tmp/top3.txt` 에 저장하세요. 폴더는 빼고 파일만, 세 줄이어야 합니다.', '`find` 의 `-printf ''%s %p\\n''` 은 바이트 크기와 경로를 한 줄에 찍어 줍니다. 숫자라서 `sort -rn` 으로 큰 순서 정렬이 되고, `head -n 3` 으로 위 세 줄만 남기세요. (`-type f` 로 폴더 제외)', 'find /tmp/lab -type f -printf ''%s %p\\n'' | sort -rn | head -n 3 > /tmp/top3.txt
cat /tmp/top3.txt

# 크기를 바이트 숫자로 뽑으면 단위 걱정 없이 sort -rn. 파일을 찾는 find 와 정렬하는 sort 를 이어 붙인 형태', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab/logs /tmp/lab/data /tmp/lab/media /tmp/lab/many; head -c 3145728 /dev/zero > /tmp/lab/logs/app.log; head -c 12582912 /dev/zero > /tmp/lab/logs/db.log; head -c 524288 /dev/zero > /tmp/lab/logs/old.log; head -c 20971520 /dev/zero > /tmp/lab/data/dump.sql; head -c 5767168 /dev/zero > /tmp/lab/data/cache.bin; head -c 31457280 /dev/zero > /tmp/lab/media/movie.bin; head -c 3670016 /dev/zero > /tmp/lab/media/thumb.bin; for i in $(seq 1 300); do echo x > /tmp/lab/many/f$i; done; true"]', '["sh", "-c", "( [ \\"$(wc -l < /tmp/top3.txt)\\" -eq 3 ] ) && ( sed -n 1p /tmp/top3.txt | grep -q \\"/tmp/lab/media/movie.bin$\\" ) && ( sed -n 2p /tmp/top3.txt | grep -q \\"/tmp/lab/data/dump.sql$\\" ) && ( sed -n 3p /tmp/top3.txt | grep -q \\"/tmp/lab/logs/db.log$\\" )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "세 줄이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/top3.txt)\\" -eq 3 ]"]}, {"label": "1등이 movie.bin 이다", "cmd": ["sh", "-c", "sed -n 1p /tmp/top3.txt | grep -q \\"/tmp/lab/media/movie.bin$\\""]}, {"label": "2등이 dump.sql 이다", "cmd": ["sh", "-c", "sed -n 2p /tmp/top3.txt | grep -q \\"/tmp/lab/data/dump.sql$\\""]}, {"label": "3등이 db.log 이다", "cmd": ["sh", "-c", "sed -n 3p /tmp/top3.txt | grep -q \\"/tmp/lab/logs/db.log$\\""]}]', '[{"title": "GNU coreutils 매뉴얼 (df, du, ls, sort)", "url": "https://www.gnu.org/software/coreutils/manual/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 226 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 226, 10, '지웠는데 용량이 안 줄 때', '로그 파일을 `rm` 으로 지웠는데 `df -h` 의 사용률은 그대로이고, `du` 로 폴더를 재 봐도 그 파일은 이미 없습니다. 가장 흔한 원인은 무엇일까요?', '`df` 는 파일시스템이 실제로 쓰는 블록을, `du` 는 눈에 보이는 파일을 합산합니다. 둘이 어긋나는 이유를 생각해 보세요.', NULL, NULL, '[]', 'choice', '["`du` 가 오래 걸려서 아직 계산 중이라 그렇다", "지운 파일을 어떤 프로세스가 아직 열고 있어서, 프로세스가 닫을 때까지 공간이 반환되지 않는다", "`rm` 은 파일을 휴지통으로 옮기기 때문에 공간이 그대로다", "`df` 는 몇 시간에 한 번만 갱신되는 캐시를 보여 준다"]', 1, '프로세스가 열고 있는 파일은 `rm` 으로 이름(디렉터리 항목)만 사라지고, 데이터 블록은 프로세스가 닫을 때까지 남습니다. 그래서 `du`(보이는 파일 합계)에는 안 잡히고 `df`(실제 사용 블록)에는 그대로 잡힙니다. `lsof +L1` 로 찾고 프로세스를 재시작(또는 `: > 파일` 로 비우기)하면 해결됩니다. 리눅스 `rm` 에는 휴지통이 없고, `df` 는 호출할 때마다 현재 값을 읽습니다.', NULL, NULL, NULL, '[{"title": "GNU coreutils 매뉴얼 (df, du, ls, sort)", "url": "https://www.gnu.org/software/coreutils/manual/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 226 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 226, 11, '지우기 전후 크기 비교', '`/tmp/lab/logs` 에서 가장 큰 파일 `db.log` 를 지우려고 합니다. 지우기 **전** 폴더 크기를 `/tmp/before.txt`, 지운 **후** 크기를 `/tmp/after.txt` 에 각각 `du -sh` 결과로 저장하세요. (`app.log`, `old.log` 는 남겨 둡니다)', '순서가 중요해요. 먼저 `du -sh` 를 `before.txt` 로 저장 → `rm /tmp/lab/logs/db.log` → 다시 `du -sh` 를 `after.txt` 로 저장. 지우기 전에는 항상 무엇을 지우는지 한 번 더 확인하세요.', 'du -sh /tmp/lab/logs > /tmp/before.txt
rm /tmp/lab/logs/db.log
du -sh /tmp/lab/logs > /tmp/after.txt
cat /tmp/before.txt /tmp/after.txt

# 16M -> 약 3.6M. 정리 작업은 "전 크기 기록 -> 삭제 -> 후 크기 확인"으로 효과를 증명해 두면 보고하기도 좋다', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab/logs /tmp/lab/data /tmp/lab/media /tmp/lab/many; head -c 3145728 /dev/zero > /tmp/lab/logs/app.log; head -c 12582912 /dev/zero > /tmp/lab/logs/db.log; head -c 524288 /dev/zero > /tmp/lab/logs/old.log; head -c 20971520 /dev/zero > /tmp/lab/data/dump.sql; head -c 5767168 /dev/zero > /tmp/lab/data/cache.bin; head -c 31457280 /dev/zero > /tmp/lab/media/movie.bin; head -c 3670016 /dev/zero > /tmp/lab/media/thumb.bin; for i in $(seq 1 300); do echo x > /tmp/lab/many/f$i; done; true"]', '["sh", "-c", "( grep -q \\"^16M[[:space:]]/tmp/lab/logs$\\" /tmp/before.txt ) && ( grep -Eq \\"^3\\\\.[0-9]M[[:space:]]/tmp/lab/logs$\\" /tmp/after.txt ) && ( [ ! -e /tmp/lab/logs/db.log ] ) && ( [ -f /tmp/lab/logs/app.log ] && [ -f /tmp/lab/logs/old.log ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "before 가 16M 이다", "cmd": ["sh", "-c", "grep -q \\"^16M[[:space:]]/tmp/lab/logs$\\" /tmp/before.txt"]}, {"label": "after 가 3.x M 로 줄었다", "cmd": ["sh", "-c", "grep -Eq \\"^3\\\\.[0-9]M[[:space:]]/tmp/lab/logs$\\" /tmp/after.txt"]}, {"label": "db.log 는 지워졌다", "cmd": ["sh", "-c", "[ ! -e /tmp/lab/logs/db.log ]"]}, {"label": "나머지 로그는 남아 있다", "cmd": ["sh", "-c", "[ -f /tmp/lab/logs/app.log ] && [ -f /tmp/lab/logs/old.log ]"]}]', '[{"title": "GNU coreutils 매뉴얼 (df, du, ls, sort)", "url": "https://www.gnu.org/software/coreutils/manual/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 226 AND order_index = 11);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 226, 12, '디스크가 찼을 때 찾는 순서', '서버 디스크가 거의 찼다는 알람을 받았습니다. 원인을 좁혀 가는 흐름을 **앞에서 뒤**로 놓으세요.', '넓게 보고 → 폴더 단위로 좁히고 → 파일을 찾아 정리 → 효과 확인 순서입니다.', NULL, NULL, '[]', 'order', '["`df -h` 로 어느 파일시스템(마운트)이 찼는지 확인한다", "찬 곳에서 `du -h --max-depth=1 경로 | sort -rh` 로 큰 폴더를 찾아 한 단계씩 내려간다", "큰 폴더 안에서 `find 경로 -type f -size +100M` 이나 `ls -lhS` 로 큰 파일을 찾는다", "불필요한 파일을 확인 후 지우고 `df -h` 로 사용률이 줄었는지 다시 본다"]', NULL, '**`df` 로 어느 디스크가 찼는지 → `du` 로 큰 폴더로 좁히기 → `find`/`ls -lhS` 로 큰 파일 찾기 → 정리 후 `df` 로 확인** 입니다. 처음부터 `du /` 로 전체를 재면 오래 걸리고 다른 디스크까지 섞이니, 먼저 `df` 로 범위를 정합니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "GNU coreutils 매뉴얼 (df, du, ls, sort)", "url": "https://www.gnu.org/software/coreutils/manual/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 226 AND order_index = 12);

UPDATE quest_set SET display_order = 171, unit_id = (SELECT id FROM unit WHERE id = 4), icon = '💽' WHERE id = 226;
